const TIMEZONE = "America/Sao_Paulo";
const LOGO_URL = "https://biodinamica.com.br/IU/logobiodinamica.png";

function todayInTZ() {
  const now = new Date();
  const parts = new Intl.DateTimeFormat("en-CA", {
    timeZone: TIMEZONE,
    year: "numeric",
    month: "2-digit",
    day: "2-digit",
  }).formatToParts(now);
  const map = Object.fromEntries(parts.map((p) => [p.type, p.value]));
  return new Date(`${map.year}-${map.month}-${map.day}T00:00:00`);
}

function lastDayOfMonth(year, monthIndex) {
  return new Date(year, monthIndex + 1, 0).getDate();
}

function nextMonthlyOccurrence(day, today) {
  const clampedDay = (year, monthIndex) => Math.min(day, lastDayOfMonth(year, monthIndex));
  const thisMonth = new Date(
    today.getFullYear(),
    today.getMonth(),
    clampedDay(today.getFullYear(), today.getMonth())
  );
  if (thisMonth >= today) return thisMonth;
  const nextMonthIndex = today.getMonth() + 1;
  const year = today.getFullYear() + Math.floor(nextMonthIndex / 12);
  const monthIndex = nextMonthIndex % 12;
  return new Date(year, monthIndex, clampedDay(year, monthIndex));
}

function formatDateBR(date) {
  return date.toLocaleDateString("pt-BR", { day: "2-digit", month: "2-digit", year: "numeric" });
}

function escapeHtml(str) {
  return String(str)
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;");
}

const today = todayInTZ();
const matches = [];

for (const item of items) {
  const sub = item.json;
  if (sub.recurrence_type !== "monthly_day" && sub.recurrence_type !== "fixed_date") continue;

  let dueDate;
  if (sub.recurrence_type === "fixed_date") {
    if (!sub.recurrence_date) continue;
    dueDate = new Date(`${sub.recurrence_date}T00:00:00`);
  } else {
    if (!sub.recurrence_day) continue;
    dueDate = nextMonthlyOccurrence(Number(sub.recurrence_day), today);
  }

  // Aviso normal: 1 dia antes do vencimento.
  // Se esse dia cair num domingo, avisa na sexta-feira anterior.
  const notifyDate = new Date(dueDate);
  notifyDate.setDate(notifyDate.getDate() - 1);
  if (notifyDate.getDay() === 0) {
    notifyDate.setDate(notifyDate.getDate() - 2);
  }

  if (notifyDate.getTime() === today.getTime()) {
    matches.push({
      platform: sub.platform,
      subject: sub.subject,
      amount: sub.amount,
      currency: sub.currency || "BRL",
      dueDate: formatDateBR(dueDate),
    });
  }
}

const lines = matches.map((m) => {
  const valor = m.amount != null ? ` — ${m.currency} ${Number(m.amount).toFixed(2)}` : "";
  const assunto = m.subject ? ` (${m.subject})` : "";
  return `- ${m.platform}${assunto}: vence em ${m.dueDate}${valor}`;
});

const subject = `Aviso de vencimento - ${matches.length} assinatura${matches.length === 1 ? "" : "s"}`;
const bodyText = `Assinaturas com vencimento proximo:\n\n${lines.join("\n")}\n\nEnviado automaticamente pelo n8n.`;

const rowsHtml = matches
  .map((m) => {
    const valor = m.amount != null ? `${m.currency} ${Number(m.amount).toFixed(2)}` : "";
    const assunto = m.subject ? ` <span style="font-weight:400;color:#77816a;">(${escapeHtml(m.subject)})</span>` : "";
    return `
              <tr>
                <td style="padding:0 0 10px 0;">
                  <table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background-color:#f7f8f2;border-left:4px solid #6b7f2e;border-radius:6px;">
                    <tr>
                      <td style="padding:14px 18px;">
                        <table role="presentation" width="100%" cellpadding="0" cellspacing="0">
                          <tr>
                            <td style="font-size:15px;font-weight:700;color:#3d4a1a;font-family:Arial, Helvetica, sans-serif;">${escapeHtml(m.platform)}${assunto}</td>
                            <td align="right" style="font-size:15px;font-weight:700;color:#3d4a1a;font-family:Arial, Helvetica, sans-serif;white-space:nowrap;">${escapeHtml(valor)}</td>
                          </tr>
                          <tr>
                            <td colspan="2" style="font-size:13px;color:#77816a;padding-top:4px;font-family:Arial, Helvetica, sans-serif;">Vence em ${escapeHtml(m.dueDate)}</td>
                          </tr>
                        </table>
                      </td>
                    </tr>
                  </table>
                </td>
              </tr>`;
  })
  .join("");

const bodyHtml = `<!DOCTYPE html>
<html lang="pt-BR">
  <head>
    <meta charset="UTF-8" />
    <meta name="viewport" content="width=device-width, initial-scale=1.0" />
    <title>${escapeHtml(subject)}</title>
  </head>
  <body style="margin:0;padding:0;background-color:#eef0e6;font-family:Arial, Helvetica, sans-serif;">
    <table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background-color:#eef0e6;padding:32px 16px;">
      <tr>
        <td align="center">
          <table role="presentation" width="600" cellpadding="0" cellspacing="0" style="max-width:600px;width:100%;background-color:#ffffff;border-radius:10px;overflow:hidden;box-shadow:0 2px 10px rgba(61,74,26,0.08);">
            <tr>
              <td style="padding:36px 40px 20px 40px;text-align:center;border-bottom:1px solid #eef0e6;">
                <img src="${LOGO_URL}" alt="Biodinâmica" width="200" style="display:block;margin:0 auto;border:0;outline:none;text-decoration:none;height:auto;max-width:100%;" />
              </td>
            </tr>
            <tr>
              <td style="padding:28px 40px 4px 40px;">
                <h1 style="margin:0 0 6px 0;font-size:20px;line-height:1.3;color:#3d4a1a;font-family:Arial, Helvetica, sans-serif;">Aviso de vencimento</h1>
                <p style="margin:0;font-size:14px;line-height:1.5;color:#6b7660;font-family:Arial, Helvetica, sans-serif;">
                  ${matches.length === 1 ? "A assinatura abaixo vence em breve" : "As assinaturas abaixo vencem em breve"}:
                </p>
              </td>
            </tr>
            <tr>
              <td style="padding:18px 40px 32px 40px;">
                <table role="presentation" width="100%" cellpadding="0" cellspacing="0">${rowsHtml}
                </table>
              </td>
            </tr>
            <tr>
              <td style="background-color:#f7f8f2;padding:20px 40px;text-align:center;border-top:1px solid #eef0e6;">
                <p style="margin:0;font-size:12px;line-height:1.5;color:#9aa38c;font-family:Arial, Helvetica, sans-serif;">Enviado automaticamente pelo Controle de Gastos de TI &middot; Biodin&acirc;mica</p>
              </td>
            </tr>
          </table>
        </td>
      </tr>
    </table>
  </body>
</html>`;

return [{ json: { matches, count: matches.length, subject, bodyText, bodyHtml } }];
